#include <iostream>
#include <vector>
#include <type_traits>

struct Item {
    int id;
    Item(int i) : id(i) {}
    Item(const Item&) = default;
    Item(Item&&) noexcept = default;
    Item& operator=(const Item&) = default;
    Item& operator=(Item&&) noexcept = default;
    bool operator<(const Item& other) const { return id < other.id; }
    bool operator==(const Item& other) const { return id == other.id; }
};

int main() {
    using Container = std::vector<Item>;

    // Using nested types
    Container::size_type count = 0;
    Container items;
    items.push_back(Item(10));
    items.push_back(Item(20));

    count = items.size();
    Container::value_type firstItem = items.front();

    std::cout << "Count: " << count << "\n";
    std::cout << "First item id: " << firstItem.id << "\n";
    std::cout << "Is empty: " << std::boolalpha << items.empty() << "\n";

    return 0;
}

#include <iostream>
#include <iterator>

int main() {
    // Create an input iterator bound to std::cin
    std::istream_iterator<int> inputInt(std::cin);

    // Read first integer
    int number1 = *inputInt;

    // Advance to next input integer
    ++inputInt;
    int number2 = *inputInt;

    // Create an output iterator bound to std::cout
    std::ostream_iterator<int> outputInt(std::cout);

    std::cout << "The sum is: ";
    *outputInt = number1 + number2;
    std::cout << std::endl;

    return 0;
}
